        bool online=true,removed=false;int downloaded=0;Func<string,CloudEntry> reader=path=>{var entry=CloudFiles.Read(path);if(path==file&&online){entry.Attributes|=0x1000;entry.Tag=0x9000001A;}return entry;};
        string output=CloudFiles.DownloadAndRemove(new[]{root},true,CancellationToken.None,null,reader,(entry,token)=>{downloaded++;online=false;},()=>{removed=true;return "OK";});check(downloaded==1&&removed&&File.ReadAllText(file)=="local fixture","OneDrive download mode rechecks local availability before calling uninstall and preserves file content");
        online=true;removed=false;check(Rejects(()=>CloudFiles.DownloadAndRemove(new[]{root},true,CancellationToken.None,null,reader,(entry,token)=>{},()=>{removed=true;return "OK";}))&&!removed,"unconfirmed OneDrive download blocks uninstall");
        removed=false;output=CloudFiles.DownloadAndRemove(new[]{root},false,CancellationToken.None,null,reader,(entry,token)=>{throw new Exception("Must not download");},()=>{removed=true;return "OK";});check(removed&&output.Contains(L.T("AVISO","WARNING"))&&online,"explicit continue-without-download keeps online content and reports the warning");
        removed=false;string newFile=Path.Combine(root,"arrived.bin");check(Rejects(()=>CloudFiles.DownloadAndRemove(new[]{root},true,CancellationToken.None,null,path=>{var entry=reader(path);if(path==newFile)entry.Attributes|=0x1000;return entry;},(entry,token)=>{online=false;File.WriteAllText(newFile,"new cloud placeholder fixture");},()=>{removed=true;return "OK";}))&&!removed,"a new online file found after download prevents OneDrive uninstall");File.Delete(newFile);online=true;
        removed=false;using(var cancel=new CancellationTokenSource()){cancel.Cancel();check(Rejects(()=>CloudFiles.DownloadAndRemove(new[]{root},true,cancel.Token,null,reader,(entry,token)=>{},()=>{removed=true;return "OK";}))&&!removed,"canceling OneDrive preparation cannot invoke uninstall");}
        check(!CloudFiles.Within(root+"-other\\file",root)&&CloudFiles.Within(file,root),"OneDrive containment checks reject a same-prefix sibling path");
        var denied=Runner.Run(System.Reflection.Assembly.GetExecutingAssembly().Location,"--hydrate-onedrive "+Args.Q(Path.Combine(folder,"outside-cloud.txt")),10000);check(denied.Code!=0,"native hydration helper rejects a path outside registered OneDrive roots");
        using(var cancel=new CancellationTokenSource()){cancel.CancelAfter(300);var watch=Stopwatch.StartNew();var result=Runner.Run(System.Reflection.Assembly.GetExecutingAssembly().Location,"--test-command-child",10000,null,null,cancel.Token);check(result.Code==-3&&watch.Elapsed.TotalSeconds<5,"download command cancellation terminates only its own worker and returns promptly");}
        foreach(string image in new[]{"pix.png","kofi.png","instagram.png","links.png"})check(File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","branding",image)),"farewell reuses the supplied "+image+" QR asset");
    }
}
